import"chrome://resources/ash/common/cr_elements/cr_dialog/cr_dialog.js";import"chrome://resources/mojo/mojo/public/mojom/base/big_buffer.mojom-webui.js";import"chrome://resources/mojo/mojo/public/mojom/base/string16.mojom-webui.js";import"./icons.html.js";import"./firmware_shared.css.js";import"./firmware_shared_fonts.css.js";import"./strings.m.js";import{I18nMixin}from"chrome://resources/ash/common/cr_elements/i18n_mixin.js";import{mojoString16ToString}from"chrome://resources/js/mojo_type_util.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./firmware_confirmation_dialog.html.js";import{isAppV2Enabled}from"./firmware_update_utils.js";const FirmwareConfirmationDialogElementBase=I18nMixin(PolymerElement);export class FirmwareConfirmationDialogElement extends FirmwareConfirmationDialogElementBase{constructor(){super(...arguments);this.open=false;this.shouldShowDisclaimer=false}static get is(){return"firmware-confirmation-dialog"}static get template(){return getTemplate()}static get properties(){return{update:{type:Object},open:{type:Boolean,value:false},shouldShowDisclaimer:{type:Boolean,value:false}}}connectedCallback(){super.connectedCallback();window.addEventListener("open-confirmation-dialog",(e=>this.onOpenConfirmationDialog(e)));this.shouldShowDisclaimer=isAppV2Enabled()}openUpdateDialog(){this.closeDialog();this.dispatchEvent(new CustomEvent("open-update-dialog",{bubbles:true,composed:true,detail:{update:this.update,inflight:false}}))}closeDialog(){this.open=false}computeTitle(){return this.i18n("confirmationTitle",mojoString16ToString(this.update.deviceName))}onOpenConfirmationDialog(event){this.update=event.detail.update;this.open=true}}customElements.define(FirmwareConfirmationDialogElement.is,FirmwareConfirmationDialogElement);